      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
    ],
    [
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
    ],
    [
