      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
    ],
    [
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
    ],
    [
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: 0, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
    ],
    [
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
      { colorNo: -1, check: false, condition: 9 },
    ],
  ],
  total: {
    redSheet: 0,
    greenSheet: 0,
    whiteSheet: 0,
    blueSheet: 0,
  }
}

// パネル更新
// 各方向で対象となるパネルに対して更新処理を行う
// パネル更新（上方向）（col:対象色番号,v:縦番号,s:横番号,pan:パネル,total:パネル集計,sheet:パネル変化枚数）
// export const upPanelChenge = (col: number, v: number, s: number, pan: Panel[][], total: Total, sheet: number): number => {
  export const upPanelChenge = (col: number, v: number, s: number, total: Total, sheet: number): number => {
  // パネル内容
  let pContext = useContext(PanelContext) 
  sheets = sheet
  for (i = v - 1; i >= 0; i--) {
    if (pContext[i][s].colorNo !== col && pContext[i][s].colorNo > COLORS.YELLOW) {
      PanelChangeTime(col, i, s, pContext, total)
      // sleep(0.8,() => {console.log('時間経過')})
      // panelChangeExec(col, i, s, pan, total)
      // sleep(0.8 ,() => {panelChangeExec(col, i, s, pan, total)})
    } else {
      break
    }
  }
  return sheets
}
// パネル更新（下方向）（col:対象色番号,v:縦番号,s:横番号,pan:パネル,total:パネル集計,sheet:パネル変化枚数）
// export const downPanelChenge = (col: number, v: number, s: number, pan: Panel[][], total: Total, sheet: number): number => {
export const downPanelChenge = (col: number, v: number, s: number, total: Total, sheet: number): number => {
  // パネル内容
  let pContext = useContext(PanelContext) 
  sheets = sheet
  for (i = v + 1; i <= 6; i++) {
    if (pContext[i][s].colorNo !== col && pContext[i][s].colorNo > COLORS.YELLOW) {
      PanelChangeTime(col, i, s, pContext, total)
      // sleep(0.8,() => {console.log('時間経過')})
      // panelChangeExec(col, i, s, pan, total)
      // sleep(0.8, () => {panelChangeExec(col, i, s, pan, total)})
    } else {
      break
    }
  }
  return sheets
}
// パネル更新（左方向）（col:対象色番号,v:縦番号,s:横番号,pan:パネル,total:パネル集計,sheet:パネル変化枚数）
// export const leftPanelChenge = (col: number, v: number, s: number, pan: Panel[][], total: Total, sheet: number): number => {
export const leftPanelChenge = (col: number, v: number, s: number, total: Total, sheet: number): number => {
  // パネル内容
  let pContext = useContext(PanelContext) 
  sheets = sheet
  for (i = s - 1; i >= 0; i--) {
    if (pContext[v][i].colorNo !== col && pContext[v][i].colorNo > COLORS.YELLOW) {
      PanelChangeTime(col, v, i, pContext, total)
      // sleep(0.8,() => {console.log('時間経過')})
      // panelChangeExec(col, v, i, pan, total)
      // sleep(0.8, () => {panelChangeExec(col, v, i, pan, total)})
    } else {
      break
    }
  }
  return sheets
}
// パネル更新（右方向）（col:対象色番号,v:縦番号,s:横番号,pan:パネル,total:パネル集計,sheet:パネル変化枚数）
