export const rightPanelChenge = (col: number, v: number, s: number, total: Total, sheet: number): number => {
  // パネル内容
  let pContext = useContext(PanelContext) 
  sheets = sheet
  for (i = s + 1; i <= 6; i++) {
    if (pContext[v][i].colorNo !== col && pContext[v][i].colorNo > COLORS.YELLOW) {
      PanelChangeTime(col, v, i, pContext, total)
      // sleep(0.8,() => {console.log('時間経過')})
      // panelChangeExec(col, v, i, pan, total)
      // sleep(0.8, () => {panelChangeExec(col, v, i, pan, total)})
    } else {
      break
    }
  }
  return sheets
}
// パネル更新（左斜め上方向）（col:対象色番号,v:縦番号,s:横番号,pan:パネル,total:パネル集計,sheet:パネル変化枚数）
// export const leftUpPanelChenge = (col: number, v: number, s: number, pan: Panel[][], total: Total, sheet: number): number => {
export const leftUpPanelChenge = (col: number, v: number, s: number, total: Total, sheet: number): number => {
  // パネル内容
  let pContext = useContext(PanelContext) 
  sheets = sheet
  for (i = v - 1, j = s - 1; i >= 0 || j >= 0; i--, j--) {
    if (pContext[i][j].colorNo !== col && pContext[i][j].colorNo > COLORS.YELLOW) {
      PanelChangeTime(col, i, j, pContext, total)
      // sleep(0.8,() => {console.log('時間経過')})
      // panelChangeExec(col, i, j, pan, total)
      // sleep(0.8, () => {panelChangeExec(col, i, j, pan, total)})
    } else {
      break
    }
  }
  return sheets
}
// パネル更新（左斜め下方向）（col:対象色番号,v:縦番号,s:横番号,pan:パネル,total:パネル集計,sheet:パネル変化枚数）
