export const leftDownPanelChenge = (col: number, v: number, s: number, total: Total, sheet: number): number => {
  // パネル内容
  let pContext = useContext(PanelContext) 
  sheets = sheet
  for (i = v + 1, j = s - 1; i <= 6 || j >= 0; i++, j--) {
    if (pContext[i][j].colorNo !== col && pContext[i][j].colorNo > COLORS.YELLOW) {
      PanelChangeTime(col, i, j, pContext, total)
      // sleep(0.8,() => {console.log('時間経過')})
      // panelChangeExec(col, i, j, pan, total)
      // sleep(0.8, () => {panelChangeExec(col, i, j, pan, total)})
    } else {
      break
    }
  }
  return sheets
}
